import { Effect, Stream, Predicate } from "effect"

const s = Stream.make(1, 2, 3)
console.log("isStream", Stream.isStream(s))
console.log("isEffect", Effect.isEffect(s))
console.log("hasStreamTypeId", Predicate.hasProperty(s, Stream.StreamTypeId))
console.log("typeId", s[Stream.StreamTypeId])
console.log("keys", Object.keys(s))

// try yield*
const eff = Effect.gen(function*() {
  const x = yield* s
  return x
})
console.log("yield* stream result:", Effect.runSync(eff))

import { Effect, Stream, Predicate } from "effect"

const s = Stream.make(1, 2, 3)
const e = Effect.succeed(1)
console.log("s has StreamTypeId", Predicate.hasProperty(s, Stream.StreamTypeId))
console.log("e has StreamTypeId", Predicate.hasProperty(e, Stream.StreamTypeId))
console.log("s isEffect", Effect.isEffect(s))
console.log("e isEffect", Effect.isEffect(e))

const eff = Effect.gen(function*() {
  const x = yield* s
  return x
})
console.log("yield* stream result:", Effect.runSync(eff))

