import { Schema } from "effect"
import * as AST from "effect/SchemaAST"

class A extends Schema.TaggedClass<"A">("A")({ a: Schema.String }) {}
class B extends Schema.TaggedClass<"B">("B")({ b: Schema.Number }) {}

const U = Schema.Union(A, B)
const suspended = Schema.suspend(() => Schema.Union(A, B))
const transformed = Schema.transform(Schema.Union(A, B), Schema.Union(A, B), { decode: (x) => x, encode: (x) => x })

function dump(ast: AST.AST, depth = 0): void {
  const pad = "  ".repeat(depth)
  console.log(pad + "tag:", ast._tag, ast._tag === "Transformation" ? ` from=${ast.from._tag} to=${ast.to._tag}` : "")
  if (ast._tag === "Union") {
    for (const t of ast.types) dump(t, depth + 1)
  }
}

console.log("A.ast:"); dump(A.ast)
console.log("U.ast:"); dump(U.ast)
console.log("suspended.ast:"); dump(suspended.ast)
console.log("transformed.ast:"); dump(transformed.ast)
EOF
