import { Effect, Schema, Stream } from "effect"
import { HttpClientRequest, HttpClientResponse, HttpApiSSE } from "@effect/platform"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.String }) {}
class B extends Schema.TaggedClass<B>()("B", { b: Schema.Number }) {}
const U = Schema.Union(A, B)

const wire = "event: A\ndata: {\"a\":\"hello\"}\n\nevent: B\ndata: {\"b\":42}\n\n"
const encoder = new TextEncoder()

// split wire into awkward chunks
const chunks = [0, 7, 20, 45, 55].map((_, i, arr) => {
  const start = i === 0 ? 0 : arr[i]
  const end = i === arr.length - 1 ? wire.length : arr[i + 1]
  return encoder.encode(wire.slice(start, end))
})

const response = new Response(new ReadableStream({
  start(controller) {
    for (const c of chunks) controller.enqueue(c)
    controller.close()
  }
}), { status: 200 })

const clientResponse = HttpClientResponse.fromWeb(
  HttpClientRequest.get("http://localhost/stream"),
  response
)

Effect.runPromise(
  Effect.gen(function*() {
    const stream = HttpApiSSE.toStream(clientResponse, HttpApiSSE.makeUnionEventDecoder(U))
    const events = yield* Stream.runCollect(stream)
    console.log("events:", events.toReadonlyArray().map((e) => e instanceof A ? `A:${e.a}` : `B:${e.b}`))
  })
).catch((e) => console.error("FAILED", e))
